import Foundation

/// What to read between sets: three short cues and the one mistake to watch for.
/// Draft wording, waiting for the coaches' review (see the coach doc).
struct Technique: Sendable {
    let cues: [String]
    let mistake: String
}

extension Exercise {
    var technique: Technique {
        switch id {
        case .legPress: Technique(cues: [String(localized: "Lower back and hips stay against the pad"), String(localized: "Feet shoulder-width, in the middle of the platform"), String(localized: "Knees follow your toes; don't lock them at the top")], mistake: String(localized: "Hips lift off the pad at the bottom, or the knees snap straight at the top"))
        case .legExtension: Technique(cues: [String(localized: "Machine axis level with your knee"), String(localized: "Pad just above the ankles"), String(localized: "Pause for a second at the top, lower slowly")], mistake: String(localized: "Jerking the weight up and dropping it"))
        case .legCurl: Technique(cues: [String(localized: "Machine axis level with your knee"), String(localized: "Hips pressed into the bench"), String(localized: "Lower slowly, 2–3 seconds")], mistake: String(localized: "Hips rise and the lower back takes over"))
        case .gluteBridge: Technique(cues: [String(localized: "Shoulder blades on the bench, chin to chest"), String(localized: "Shins vertical at the top"), String(localized: "Squeeze your glutes at the top")], mistake: String(localized: "Arching the lower back instead of using the glutes"))
        case .backExtension: Technique(cues: [String(localized: "Pad at the hip bones"), String(localized: "Rise to a straight line, no higher"), String(localized: "No swinging")], mistake: String(localized: "Arching past straight at the top"))
        case .chestPress: Technique(cues: [String(localized: "Handles at mid-chest height"), String(localized: "Shoulder blades squeezed and against the pad"), String(localized: "Elbows about 45° from your body")], mistake: String(localized: "Shoulders roll forward, shoulder blades leave the pad"))
        case .latPulldown: Technique(cues: [String(localized: "Thighs locked under the pads"), String(localized: "Pull to the top of your chest"), String(localized: "Elbows down, shoulders away from your ears")], mistake: String(localized: "Pulling behind the neck or swinging the body"))
        case .assistedPullUp: Technique(cues: [String(localized: "Pick a counterweight that gives 6–10 clean reps"), String(localized: "Start by pulling your shoulders down"), String(localized: "Lower slowly to straight arms")], mistake: String(localized: "Half reps and jerks"))
        case .seatedCableRow: Technique(cues: [String(localized: "Back straight, body almost still"), String(localized: "Pull to your lower belly, elbows close to your sides"), String(localized: "Squeeze your shoulder blades at the end")], mistake: String(localized: "Rocking back and forth"))
        case .machineShoulderPress: Technique(cues: [String(localized: "Handles at shoulder height to start"), String(localized: "Back against the pad"), String(localized: "Don't snap your elbows straight")], mistake: String(localized: "Arching the lower back"))
        case .tricepsPushdown: Technique(cues: [String(localized: "Elbows pinned to your sides"), String(localized: "Arms straight at the bottom"), String(localized: "Up slowly, to a right angle at the elbow")], mistake: String(localized: "Elbows wander and the body pushes the weight"))
        case .cableCurl: Technique(cues: [String(localized: "Elbows still, by your sides"), String(localized: "Body doesn't swing"), String(localized: "Lower slowly")], mistake: String(localized: "Swinging the weight up with the body"))
        case .plank: Technique(cues: [String(localized: "One straight line from head to heels"), String(localized: "Abs and glutes tight"), String(localized: "Breathe evenly")], mistake: String(localized: "Sagging lower back or hips up"))
        case .deadBug: Technique(cues: [String(localized: "Lower back stays on the floor the whole time"), String(localized: "Opposite arm and leg go down together"), String(localized: "Slowly, breathe out as you lower")], mistake: String(localized: "Lower back lifts off the floor"))
        case .gobletSquat: Technique(cues: [String(localized: "Dumbbell at your chest, elbows down"), String(localized: "Knees follow your toes"), String(localized: "Go as deep as your back stays straight")], mistake: String(localized: "Knees cave in, heels come up"))
        case .dumbbellRDL: Technique(cues: [String(localized: "Knees slightly bent, and they stay that way"), String(localized: "Hips back, dumbbells slide along your legs"), String(localized: "Go down until the back of your thighs stretches")], mistake: String(localized: "Rounded back"))
        case .splitSquat: Technique(cues: [String(localized: "Long stance, weight on the front leg"), String(localized: "Go straight down, back knee almost to the floor"), String(localized: "Torso upright")], mistake: String(localized: "Front knee caves in"))
        case .dumbbellBench: Technique(cues: [String(localized: "Shoulder blades squeezed, feet on the floor"), String(localized: "Lower to chest level, elbows at 45°"), String(localized: "Don't clang the dumbbells at the top")], mistake: String(localized: "Elbows flared to 90°, which hurts the shoulders"))
        case .oneArmRow: Technique(cues: [String(localized: "Knee and hand on the bench, back parallel to the floor"), String(localized: "Pull to your hip, elbow along your side"), String(localized: "Body doesn't twist")], mistake: String(localized: "Jerking and twisting the body"))
        case .dumbbellShoulderPress: Technique(cues: [String(localized: "Bench back almost upright"), String(localized: "Dumbbells at ear level at the bottom"), String(localized: "Lower back against the pad")], mistake: String(localized: "Arching the lower back because the weight is too heavy"))
        case .lateralRaise: Technique(cues: [String(localized: "Light weight, elbows slightly bent"), String(localized: "Up to shoulder height, no higher"), String(localized: "No swinging")], mistake: String(localized: "Shrugging and throwing the weight up with the body"))
        case .dumbbellCurl: Technique(cues: [String(localized: "Elbows still"), String(localized: "Palms up"), String(localized: "Lower slowly")], mistake: String(localized: "Swinging the body"))
        case .pushUp: Technique(cues: [String(localized: "Body straight, like a plank"), String(localized: "Hands a bit wider than shoulders, elbows at 45°"), String(localized: "Start from a bench, then move to the floor")], mistake: String(localized: "Sagging hips"))
        case .backSquat: Technique(cues: [String(localized: "Bar on your upper back, not on your neck"), String(localized: "Knees follow your toes, heels down"), String(localized: "In a rack with the safety bars set")], mistake: String(localized: "Chest drops forward, knees cave in"))
        case .benchPress: Technique(cues: [String(localized: "Eyes under the bar, shoulder blades squeezed"), String(localized: "Lower to the bottom of your chest, no bouncing"), String(localized: "Only with a spotter or in a rack with safety bars")], mistake: String(localized: "Pressing without a spotter, bouncing off the chest"))
        case .barbellRDL: Technique(cues: [String(localized: "The bar slides along your legs"), String(localized: "Knees slightly bent, hips back"), String(localized: "Back straight the whole set")], mistake: String(localized: "Rounded back"))
        case .barbellRow: Technique(cues: [String(localized: "Lean about 45°, back straight"), String(localized: "Pull to your lower belly"), String(localized: "No jerking with the body")], mistake: String(localized: "The torso straightens up and the lower back does the pulling"))
        case .hackSquat: Technique(cues: [String(localized: "Back and shoulders against the pads"), String(localized: "Feet shoulder-width, in the middle of the platform"), String(localized: "Release the safety handles before the set, lock them after")], mistake: String(localized: "Heels come off the platform"))
        case .smithSquat: Technique(cues: [String(localized: "Feet a little in front of the bar"), String(localized: "Bar on your upper back, not on your neck"), String(localized: "Set the stoppers just below your lowest point")], mistake: String(localized: "Knees cave in"))
        case .hipAbduction: Technique(cues: [String(localized: "Back against the pad, sit tall"), String(localized: "Push your knees apart, pause for a second"), String(localized: "Bring them back slowly")], mistake: String(localized: "Leaning forward and rocking"))
        case .hipAdduction: Technique(cues: [String(localized: "Back against the pad, sit tall"), String(localized: "Squeeze your knees together, pause for a second"), String(localized: "Open slowly, only as wide as is comfortable")], mistake: String(localized: "Letting the weight yank the legs open"))
        case .calfRaise: Technique(cues: [String(localized: "Balls of the feet on the edge, heels free"), String(localized: "Rise as high as you can and pause"), String(localized: "Lower slowly into a stretch")], mistake: String(localized: "Bouncing at the bottom"))
        case .cableKickback: Technique(cues: [String(localized: "Strap on the ankle, hold the frame"), String(localized: "Move the leg with your glute, not your lower back"), String(localized: "Pause at the top, return slowly")], mistake: String(localized: "Arching the lower back to swing the leg higher"))
        case .floorGluteBridge: Technique(cues: [String(localized: "Feet close to your hips, flat on the floor"), String(localized: "Push through your heels"), String(localized: "Squeeze your glutes at the top")], mistake: String(localized: "Arching the lower back instead of using the glutes"))
        case .pecDeck: Technique(cues: [String(localized: "Handles at chest height"), String(localized: "Back against the pad, elbows slightly bent"), String(localized: "Bring together slowly, open slowly")], mistake: String(localized: "Opening too wide and straining the shoulders"))
        case .cableFly: Technique(cues: [String(localized: "Step forward, lean slightly"), String(localized: "Elbows slightly bent and fixed"), String(localized: "Hands meet in front of your lower chest")], mistake: String(localized: "Turning it into a press by bending the elbows"))
        case .assistedDip: Technique(cues: [String(localized: "Pick a counterweight that gives 6–10 clean reps"), String(localized: "Lean forward slightly, elbows back"), String(localized: "Lower until your elbows are at 90°, no deeper")], mistake: String(localized: "Shoulders shrug up to the ears at the bottom"))
        case .machineRow: Technique(cues: [String(localized: "Chest against the pad"), String(localized: "Pull your elbows back, squeeze your shoulder blades"), String(localized: "Return slowly to straight arms")], mistake: String(localized: "Leaning back off the pad"))
        case .reverseFly: Technique(cues: [String(localized: "Chest against the pad, handles at shoulder height"), String(localized: "Arms slightly bent, open wide"), String(localized: "Light weight, slow")], mistake: String(localized: "Shrugging and jerking the weight"))
        case .facePull: Technique(cues: [String(localized: "Pulley at face height, rope grip"), String(localized: "Pull to your face, elbows high"), String(localized: "Pull the rope apart at the end")], mistake: String(localized: "Pulling with the body, leaning back"))
        case .cableLateralRaise: Technique(cues: [String(localized: "Stand side-on to the low pulley"), String(localized: "Up to shoulder height, no higher"), String(localized: "Lower slowly")], mistake: String(localized: "Leaning away to swing the weight up"))
        case .preacherCurl: Technique(cues: [String(localized: "Armpits snug against the top of the pad"), String(localized: "Machine axis level with your elbow"), String(localized: "Lower slowly, don't lock the elbow")], mistake: String(localized: "Lifting the arms off the pad"))
        case .overheadExtension: Technique(cues: [String(localized: "Hold the top plate of the dumbbell with both hands"), String(localized: "Elbows point up and stay close"), String(localized: "Lower behind your head slowly")], mistake: String(localized: "Elbows flare out and the lower back arches"))
        case .abCrunch: Technique(cues: [String(localized: "Feet under the rollers, hands on the handles"), String(localized: "Curl your chest down towards your hips"), String(localized: "Breathe out as you crunch")], mistake: String(localized: "Pulling with the arms instead of the abs"))
        case .kneeRaise: Technique(cues: [String(localized: "Back against the pad, forearms on the rests"), String(localized: "Bring your knees up to your chest"), String(localized: "Lower slowly, without swinging")], mistake: String(localized: "Swinging the legs with momentum"))
        }
    }
}
